//! \file
//! \brief C++17-compatible implementation of select functionality from C++ `<utility>` library.
#pragma once

#include <utility>

namespace carb::cpp
{

/**
 * Converts an enumeration to its underlying type.
 * \details Equivalent to `return static_cast<std::underlying_type_t<Enum>>(e);` Can be used to avoid converting an
 * enumeration to an integer type other than its underlying type.
 * @param e Enumeration value to convert.
 * @returns The integer value of the underlying type of `Enum`, converted from @p e.
 */
template <typename Enum>
constexpr std::underlying_type_t<Enum> to_underlying(Enum e) noexcept
{
    return static_cast<std::underlying_type_t<Enum>>(e);
}

} // namespace carb::cpp
